"use strict";(globalThis.webpackChunktemp_dir=globalThis.webpackChunktemp_dir||[]).push([[8413],{1592(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"why-wasm-not-ros","metadata":{"permalink":"/ko/blog/why-wasm-not-ros","editUrl":"https://github.com/CMaybe/cmaybe.github.io/tree/main/blog/2026-09-09-why-wasm-not-ros.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2026-09-09-why-wasm-not-ros.md","title":"\uc65c ROS/ROS 2 \ub300\uc2e0 WebAssembly\uc778\uac00","description":"Modern Robotics \uc608\uc81c\uac00 ROS\ub098 ROS 2 \ub300\uc2e0 \uc778\ud130\ub799\ud2f0\ube0c \ube0c\ub77c\uc6b0\uc800 \ub370\ubaa8\ub97c \uc704\ud55c WebAssembly\ub97c \uc0ac\uc6a9\ud558\ub294 \uc774\uc720\ub97c \uc124\uba85\ud569\ub2c8\ub2e4.","date":"2026-09-09T00:00:00.000Z","tags":[{"inline":false,"label":"Robotics","permalink":"/ko/blog/tags/robotics","description":"Robot software, systems, and experiments."},{"inline":false,"label":"WebAssembly","permalink":"/ko/blog/tags/webassembly","description":"Native-performance software in the browser."},{"inline":false,"label":"Modern Robotics","permalink":"/ko/blog/tags/modern-robotics","description":"Concepts, methods, and intuition behind rigid-body motion and robot kinematics."}],"readingTime":1.35,"hasTruncateMarker":true,"authors":[{"name":"Jaegyeom Kim","title":"Robotics Software Engineer","url":"https://github.com/CMaybe","page":{"permalink":"/ko/blog/authors/jaegyeom"},"socials":{"github":"https://github.com/CMaybe","linkedin":"https://www.linkedin.com/in/Jaegyeom-kim-185b8a2a4/"},"imageURL":"https://github.com/CMaybe.png","key":"jaegyeom"}],"frontMatter":{"slug":"why-wasm-not-ros","title":"\uc65c ROS/ROS 2 \ub300\uc2e0 WebAssembly\uc778\uac00","authors":["jaegyeom"],"tags":["robotics","webassembly","modern-robotics"],"description":"Modern Robotics \uc608\uc81c\uac00 ROS\ub098 ROS 2 \ub300\uc2e0 \uc778\ud130\ub799\ud2f0\ube0c \ube0c\ub77c\uc6b0\uc800 \ub370\ubaa8\ub97c \uc704\ud55c WebAssembly\ub97c \uc0ac\uc6a9\ud558\ub294 \uc774\uc720\ub97c \uc124\uba85\ud569\ub2c8\ub2e4."},"unlisted":false},"content":"ROS\uc640 ROS 2\ub294 \uc644\uc131\ub3c4 \ub192\uc740 \ub85c\ubd07 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e4\uae30\uc5d0 \ud6cc\ub96d\ud55c \uc120\ud0dd\uc785\ub2c8\ub2e4. \ud1b5\uc2e0, \ub3c4\uad6c, \ub4dc\ub77c\uc774\ubc84, \uc2dc\uac01\ud654 \uae30\ub2a5\uacfc \ub113\uc740 \uc0dd\ud0dc\uacc4\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uc774 \ube14\ub85c\uadf8\uc758 \ubaa9\ud45c\ub294 \uc870\uae08 \ub2e4\ub985\ub2c8\ub2e4. \uae30\uad6c\ud559, \ud50c\ub798\ub2dd, \ub3d9\uc5ed\ud559\uc758 \uc218\ud559\uc801 \uac1c\ub150\uc744 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud558\uace0 \uc2e4\ud589\ud558\uac8c \ub9cc\ub4dc\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## \ud574\uacb0\ud558\ub824\ub294 \ubb38\uc81c\uc758 \ucc28\uc774\\n\\n\uc774 \ube14\ub85c\uadf8\ub294 \uc2e4\uc81c \ub85c\ubd07\uc744 \uc6b4\uc6a9\ud558\uac70\ub098 \uc5ec\ub7ec \ud558\ub4dc\uc6e8\uc5b4 \ub178\ub4dc\ub97c \uc5f0\uacb0\ud558\ub824\ub294 \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc21c\uae30\uad6c\ud559, \uc5ed\uae30\uad6c\ud559, \ubaa8\uc158 \ud50c\ub798\ub2dd, \ub3d9\uc5ed\ud559\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc774 \ubaa9\uc801\uc785\ub2c8\ub2e4.\\n\\n\ub530\ub77c\uc11c \ub85c\ubcf4\ud2f1\uc2a4 \uac1c\ubc1c \ud658\uacbd\uc744 \ub530\ub85c \uc900\ube44\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub204\uad6c\ub098 \uc5f4\uc5b4\uc11c \uc2e4\ud589\ud560 \uc218 \uc788\ub294 \uc791\uace0 \ub3c5\ub9bd\uc801\uc778 \ud504\ub85c\uadf8\ub7a8\uc774 \ub354 \uc801\ud569\ud569\ub2c8\ub2e4.\\n\\n## WebAssembly\ub97c \uc120\ud0dd\ud55c \uc774\uc720\\n\\n- **\uc124\uce58\uac00 \ud544\uc694 \uc5c6\uc2b5\ub2c8\ub2e4.** ROS, ROS 2, workspace, \uc2dc\uc2a4\ud15c \ud328\ud0a4\uc9c0\ub97c \ub530\ub85c \uc124\uce58\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub429\ub2c8\ub2e4.\\n- **\ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc2e4\ud589\ub429\ub2c8\ub2e4.** Linux, macOS, Windows, \ubaa8\ubc14\uc77c \uae30\uae30\uc5d0\uc11c \uac19\uc740 \ud398\uc774\uc9c0\ub97c \uc5f4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- **\uc778\ud130\ub799\ud2f0\ube0c \uc2dc\uac01\ud654\uac00 \uc27d\uc2b5\ub2c8\ub2e4.** \uc2ac\ub77c\uc774\ub354\uc640 3D \ucee8\ud2b8\ub864\ub85c \ucef4\ud30c\uc77c\ub41c \uc54c\uace0\ub9ac\uc998\uc744 \uc989\uc2dc \uc2e4\ud589\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- **\ub124\uc774\ud2f0\ube0c \uad6c\ud604\uc744 \uc720\uc9c0\ud569\ub2c8\ub2e4.** \uacc4\uc0b0 \ucf54\uc5b4\ub97c JavaScript\ub85c \ub2e4\uc2dc \uc791\uc131\ud558\uc9c0 \uc54a\uace0 C++\ub97c WebAssembly\ub85c \ucef4\ud30c\uc77c\ud569\ub2c8\ub2e4.\\n- **\uacf5\uc720\uac00 \uac04\ub2e8\ud569\ub2c8\ub2e4.** \ubc31\uc5d4\ub4dc\ub098 \ub85c\ubd07 \ubbf8\ub4e4\uc6e8\uc5b4 \uc5c6\uc774 \uc815\uc801 \uc0ac\uc774\ud2b8\ub9cc\uc73c\ub85c \uc608\uc81c \uc804\uccb4\ub97c \ubc30\ud3ec\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## ROS\uc640 ROS 2\uac00 \ub354 \uc801\ud569\ud55c \uacbd\uc6b0\\n\\n\ud558\ub4dc\uc6e8\uc5b4 \ub4dc\ub77c\uc774\ubc84, \uc13c\uc11c \uc2a4\ud2b8\ub9bc, \ubd84\uc0b0 \ub178\ub4dc, \ub85c\ubd07 \uae30\uc220 \ud30c\uc77c, lifecycle \uad00\ub9ac, \ub354 \ud070 \uc790\uc728\uc8fc\ud589 \uc2a4\ud0dd\uacfc\uc758 \ud1b5\ud569\uc774 \ud544\uc694\ud558\ub2e4\uba74 ROS\ub098 ROS 2\uac00 \ub354 \uc801\ud569\ud569\ub2c8\ub2e4.\\n\\n\uc774\ub7f0 \uc694\uad6c \uc0ac\ud56d\uc740 \uc218\ud559\uc744 \uc124\uba85\ud558\ub294 \ub370 \ud544\uc694\ud55c \uae30\ub2a5\uc774\ub77c\uae30\ubcf4\ub2e4 \uc2dc\uc2a4\ud15c \ud1b5\ud569\uc5d0 \ud544\uc694\ud55c \uae30\ub2a5\uc785\ub2c8\ub2e4. ROS\uc640 ROS 2\ub294 \uc2e4\ud589 \uc911\uc778 \ub85c\ubd07 \uc2dc\uc2a4\ud15c\uc744 \uad6c\uc131\ud558\uace0, WebAssembly\ub294 \uacc4\uc0b0 \ucf54\ub4dc\ub97c \uc6f9 \ud398\uc774\uc9c0 \uc548\uc5d0\uc11c \uc2e4\ud589\ud558\ub3c4\ub85d \ud328\ud0a4\uc9d5\ud569\ub2c8\ub2e4.\\n\\n## \uc2e4\uc81c \uc801\uc6a9 \ubc94\uc704\\n\\n\ube0c\ub77c\uc6b0\uc800 \ub370\ubaa8\ub294 \uc54c\uace0\ub9ac\uc998 \ucf54\uc5b4\ub97c \uc791\uace0 \uad00\ucc30\ud558\uae30 \uc26c\uc6b4 \ud615\ud0dc\ub85c \uc720\uc9c0\ud569\ub2c8\ub2e4. \uc2e4\uc81c \ub85c\ubd07 \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\uc11c\ub294 \uac19\uc740 C++ \uac1c\ub150\uc744 ROS\ub098 ROS 2 \ub178\ub4dc \uc548\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubbf8\ub4e4\uc6e8\uc5b4\uac00 \ud50c\ub798\ub108\uc640 \ucee8\ud2b8\ub864\ub7ec\ub97c \uc13c\uc11c, \uc561\ucd94\uc5d0\uc774\ud130, \ub2e4\ub978 \ud504\ub85c\uc138\uc2a4\uc640 \uc5f0\uacb0\ud558\uba74 \ub429\ub2c8\ub2e4.\\n\\n\uc774 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c WebAssembly\ub294 \uc54c\uace0\ub9ac\uc998 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \ud45c\ud604\uacfc \ubc30\ud3ec\ub97c \uc704\ud55c \uc120\ud0dd\uc785\ub2c8\ub2e4. \uc2e4\ud5d8\uc758 \uc9c4\uc785 \uc7a5\ubcbd\uc744 \ub0ae\ucd94\uba74\uc11c\ub3c4 \ub85c\ubcf4\ud2f1\uc2a4 \uad6c\ud604\uc744 \ub124\uc774\ud2f0\ube0c C++ \ucf54\ub4dc\uc5d0 \uac00\uae5d\uac8c \uc720\uc9c0\ud569\ub2c8\ub2e4."}]}}')}}]);